def __init__(self, f1, input_format, shuffle):
    content, labels = [], []
    lines = open(f1).readlines()
    if shuffle:
        random.shuffle(lines)
    for line in lines:
        instance = json.loads(line)
        context = instance["context"]
        completions = instance["completions"]
        answer = int(instance["answer"])
        for idx, opt in enumerate(completions):
            if input_format == "0":
                content.append(f"{context} {opt}")
            else:
                content.append(f"Story: {context} {opt}")
        # labels: one-hot per choice
        for i in range(len(completions)):
            labels.append(1 if i==answer else 0)
    self.content, self.labels = content, labels

